CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT UNIQUE,name TEXT NOT NULL,password TEXT NOT NULL,admin INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS packs (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,summary TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,tags TEXT NOT NULL,version TEXT NOT NULL,downloads INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL,updated TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',revision INTEGER NOT NULL DEFAULT 1,review_note TEXT NOT NULL DEFAULT '',reviewed_by TEXT,reviewed_at TEXT);
CREATE TABLE IF NOT EXISTS files (id TEXT PRIMARY KEY,pack_id TEXT NOT NULL REFERENCES packs(id) ON DELETE CASCADE,kind TEXT NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY,pack_id TEXT NOT NULL REFERENCES packs(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY,pack_id TEXT NOT NULL REFERENCES packs(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS packs_updated ON packs(updated);
CREATE INDEX IF NOT EXISTS files_pack ON files(pack_id);
CREATE INDEX IF NOT EXISTS comments_pack ON comments(pack_id,created);
CREATE TABLE IF NOT EXISTS user_phones (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,phone TEXT UNIQUE NOT NULL,verified INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS unverified_contacts (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,channel TEXT NOT NULL,contact TEXT NOT NULL,PRIMARY KEY(user_id,channel));
CREATE TABLE IF NOT EXISTS user_blocks (user_id TEXT PRIMARY KEY REFERENCES users(id),actor_id TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admin_contact (id INTEGER PRIMARY KEY CHECK(id=1),content TEXT NOT NULL,revision INTEGER NOT NULL);
INSERT OR IGNORE INTO admin_contact VALUES(1,'',0);
CREATE TABLE IF NOT EXISTS traffic (period TEXT PRIMARY KEY,bytes INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS review_mail_state (id INTEGER PRIMARY KEY CHECK(id=1),generation INTEGER NOT NULL,sent_generation INTEGER NOT NULL,retry_after INTEGER NOT NULL,last_sent INTEGER NOT NULL,last_error TEXT NOT NULL);
INSERT OR IGNORE INTO review_mail_state VALUES(1,0,0,0,0,'');
